/* Additive integration: question factories, validators and CERMAT points stay in app.js. */
(function(root){
  'use strict';
  const G=root.CermatGeometry,P=root.CermatPaper,copy=G.clone;
  let store,editor=null,active=null,legacy={},fact=null,deadline=0,clockPaused=false,rendering=false,saving=false,revision=0,lastTimerSave=0,observer=null,toolbarObserver=null;
  const expanded=new Set(),settings={tool:'navigate',color:'#24334a',width:2.4,size:32,snap:true,length:'',radius:'',angle:'',text:'',label:''};
  const e=value=>P.safe(value);
  const js=value=>e(JSON.stringify(String(value)));
  const tools={navigate:'Prohlížet',pencil:'Tužka',select:'Vybrat a přesunout',erase:'Guma',segment:'Úsečka',line:'Přímka',ruler:'Pravítko',circle:'Kružítko · kružnice',arc:'Kružítko · oblouk',angle:'Úhloměr',point:'Bod s názvem',triangle:'Trojúhelník',rect:'Obdélník',polygon:'Mnohoúhelník',highlight:'Zvýrazňovač',text:'Text a výpočty',pan:'Posun a přiblížení'};
  function selectFact(){
    const facts=root.CERMAT_FACTS||[];if(!facts.length)return null;
    let previous='';try{previous=localStorage.getItem('cermat-last-fact')||'';}catch(_){}
    const pool=facts.filter(item=>item.id!==previous),next=(pool.length?pool:facts)[Math.floor(Math.random()*(pool.length||facts.length))];
    try{localStorage.setItem('cermat-last-fact',next.id);}catch(_){}return next;
  }
  function factMarkup(){return fact?`<section class="fact-editorial" aria-labelledby="fact-heading"><div class="editorial-label" id="fact-heading">Věděl jsi, že…?</div><h2>${e(fact.title)}</h2><p>${e(fact.text)}</p><div class="fact-bottom"><a href="${e(fact.sourceUrl)}" target="_blank" rel="noopener">Ověřit ve zdroji</a><button class="text-button" onclick="CermatUpgrade.nextFact()">Další zajímavost <span aria-hidden="true">→</span></button></div></section>`:'';}
  function officialYear(test){const y=test.officialSource?.year;return Number.isInteger(y)&&test.officialSource.authority==='CERMAT'?y:null;}
  function saved(test){return store?.records.get(test.id)?.status==='in-progress'?store.records.get(test.id):null;}
  function answeredCount(record){return Object.values(record.answers||{}).filter(value=>Array.isArray(value)?value.some(x=>x!==null&&x!==undefined):value!==''&&value!==undefined&&value!==null).length;}
  function score(test){const value=stats[test.id];return value?Math.round(value.best)+' %':'—';}
  function progressMarkup(test){const draft=saved(test);return draft?`<span class="draft-mark">Rozepsáno · ${answeredCount(draft)}/${draft.questions.length} odpovědí</span>`:stats[test.id]?'<span class="completion-mark">Dokončeno</span>':'<span class="mut">Zatím nespuštěno</span>';}
  function startButton(test,index){return `<button class="p" onclick="startT(tests[${index}])" aria-label="${saved(test)?'Pokračovat v testu':'Spustit test'} ${e(test.title)}">${saved(test)?'Pokračovat':'Spustit'}</button>`;}
  function termRow(test,index){
    const source=test.officialSource;
    return `<div class="year-term" data-exam-id="${e(test.id)}"><div class="term-main"><h4>${e(source.examTerm||test.title)}</h4><div class="term-meta">${test.questions.length} úloh <span>·</span> ${test.minutes?test.minutes+' min':'bez limitu'} <span>·</span> ${tpts(test)} bodů</div>${progressMarkup(test)}${test.reviewQuestionCount?`<span class="term-review">K ruční kontrole: ${test.reviewQuestionCount} ${test.reviewQuestionCount===1?'podúloha':test.reviewQuestionCount<5?'podúlohy':'podúloh'}. <a href="${e(source.sourcePdf)}" target="_blank" rel="noopener">Celé zadání PDF</a></span>`:''}</div><div class="term-score"><span>Nejlepší</span><strong>${score(test)}</strong></div><div class="term-actions">${startButton(test,index)}</div></div>`;
  }
  
  function library(){
    const groups=new Map();
    tests.forEach((test,index)=>{
      if(filt&&!((test.title||'')+' '+(test.officialSource?.examTerm||'')).toLowerCase().includes(filt))return;
      const year=officialYear(test);if(year){if(!groups.has(year))groups.set(year,[]);groups.get(year).push({test,index});}
    });
    const years=[...groups.keys()].sort((a,b)=>b-a);
    if(!expanded.size&&years.length&&!library.initialized){expanded.add(years[0]);library.initialized=true;}
    const cards=years.map(year=>{
      const exams=groups.get(year),unfinished=exams.filter(x=>saved(x.test)).length,done=exams.filter(x=>stats[x.test.id]).length;
      return `<details class="tc year-card" data-year="${year}" ${expanded.has(year)||filt?'open':''}><summary><div class="year-heading"><span class="year-kicker">OFICIÁLNÍ ZADÁNÍ CERMAT</span><h3>Matematika 9 – ${year}</h3><div class="tc-tags"><span>${exams.length} ${exams.length===1?'termín':exams.length<5?'termíny':'termínů'}</span><span>${exams.reduce((n,x)=>n+x.test.questions.length,0)} úloh</span></div><small>${unfinished?`${unfinished} rozepsáno`:`${done}/${exams.length} dokončeno`}</small></div><span class="year-chevron" aria-hidden="true"></span></summary><div class="year-terms">${exams.map(({test,index})=>termRow(test,index)).join('')}</div></details>`;
    }).join('');
    return `${!filt?`<div class="mix-feature">${mixCard()}</div>`:''}${years.length?`<div class="tgrid year-grid">${cards}</div>`:''}${!years.length?'<p class="mut">Tomuto hledání neodpovídá žádný test.</p>':''}`;
  }
  function unfinishedMarkup(all=false){
    const records=[...store.records.values()].filter(r=>r.status==='in-progress').sort((a,b)=>b.updatedAt-a.updatedAt);
    if(!records.length)return '';
    return `<section class="unfinished" aria-labelledby="unfinished-heading"><div class="sech"><h2 id="unfinished-heading">Pokračuj, kde jsi skončil</h2>${!all&&records.length>3?'<button class="text-button" onclick="go(\'history\')">Všechny rozepsané testy</button>':''}</div><div class="unfinished-list">${(all?records:records.slice(0,3)).map(record=>`<div class="unfinished-row"><div><strong>${e(record.test.title)}</strong><span>${answeredCount(record)}/${record.questions.length} odpovědí · ${new Date(record.updatedAt).toLocaleString('cs-CZ',{day:'numeric',month:'numeric',hour:'2-digit',minute:'2-digit'})}</span></div><button onclick="CermatUpgrade.resume(${js(record.key)})">Pokračovat</button></div>`).join('')}</div></section>`;
  }
  function homeView(){
    return `${topNav()}<section class="study-intro"><div class="intro-copy"><div class="editorial-label">MATEMATIKA · PŘIJÍMACÍ ZKOUŠKY</div><h1>Matematika má<br> svůj řád.</h1><p>Počítej, kresli a přemýšlej. Vlastní procvičování i oficiální úlohy CERMAT na jednom místě.</p><a class="intro-link" href="#sect-tests">Vybrat zadání <span aria-hidden="true">↓</span></a></div>${factMarkup()}<figure class="comenius"><img src="data:image/jpeg;base64," width="1005" height="1286" alt="Jan Amos Komenský na rytině George Glovera z roku 1642"><figcaption>Jan Amos Komenský<span>1592–1670</span><a href="https://commons.wikimedia.org/wiki/File:Comenius_by_George_Glover.jpg" target="_blank" rel="noopener">George Glover, 1642 · volné dílo</a></figcaption></figure></section>${unfinishedMarkup()}${overview()}${root.CermatPractice?root.CermatPractice.home():''}<div class="sech" id="sect-tests"><div><span class="editorial-label">TVOJE KNIHOVNA ZADÁNÍ</span><h2>Vyber si svůj další test</h2></div><span>${tests.filter(officialYear).length} oficiálních termínů</span></div>${library()}<footer class="study-footer"><span>Cermat testy · učit se znamená rozumět</span><button class="text-button" onclick="go('progress-backup')">Záloha postupu</button></footer>`;
  }
  function navigation(){
    return `<header class="topnav"><div class="tn-in"><a class="brand study-brand" href="#" onclick="event.preventDefault();go('home')"><span class="study-monogram" aria-hidden="true">M</span><span class="bt"><b>Cermat testy</b><span>Matematika · 9. třída</span></span></a><button class="mobile-nav-toggle" aria-controls="study-navigation" aria-expanded="false" onclick="CermatUpgrade.toggleMenu(this)">Menu</button><nav class="nav" id="study-navigation" aria-label="Hlavní navigace"><button class="on" onclick="navTo('t')">Testy</button><button onclick="go('topics')">Témata</button><button onclick="navTo('o')">Můj pokrok</button><button onclick="go('history')">Rozepsané a historie</button><button onclick="go('settings')">Nastavení</button><button class="si" onclick="toggleSearch()" aria-label="Hledat test">Hledat</button></nav></div><div class="sbar" ${(sOpen||filt)?'':'hidden'}><input id="sq" type="search" aria-label="Hledat test" placeholder="Hledat rok, termín nebo test…" value="${e(fraw)}" oninput="doSearch(this)"></div></header>`;
  }
  function historyView(){
    const entries=[...store.historyMeta.values()].sort((a,b)=>b.updatedAt-a.updatedAt);
    return `<header class="sethd"><button onclick="go('home')">Zpět na testy</button><h1>Rozepsané a historie</h1></header>${unfinishedMarkup(true)}<div class="sech"><h2>Dokončené pokusy</h2><span>${entries.length}</span></div>${entries.length?`<div class="history-list">${entries.map(item=>`<article class="history-row"><div><h2>${e(item.title)}</h2><span>${new Date(item.updatedAt).toLocaleString('cs-CZ')} · ${item.total} úloh</span></div><strong>${item.score??'—'} %</strong><button onclick="CermatUpgrade.openHistory(${js(item.attemptId)})">Otevřít řešení</button></article>`).join('')}</div>`:'<p class="mut">Po odevzdání testu tu najdeš svůj výsledek i celý popsaný pracovní papír. Dosavadní nejlepší výsledky zůstávají u testů.</p>'}`;
  }
  function svgDimensions(svg){const match=/viewBox=["']([\d.\s,-]+)["']/.exec(svg);if(match){const a=match[1].trim().split(/[\s,]+/).map(Number);if(a.length===4&&a[2]>0&&a[3]>0)return a;}return[0,0,720,420];}
  function pageDefinitions(questions,record){
    const pages=[];
    for(const question of questions){
      const previous=pages.at(-1),source=question.source;
      if(previous&&source&&previous.questions[0].source?.testCode===source.testCode&&previous.questions[0].source?.parentTask===source.parentTask&&question.svg&&previous.questions[0].svg===question.svg){previous.questions.push(question);continue;}
      const svg=question.svg?cleanSvg(question.svg):'',official=source?.authority==='CERMAT',dimensions=svgDimensions(svg);
      const lines=String(question.text||'').split('\n').reduce((n,s)=>n+Math.max(1,Math.ceil(s.length/50)),0);
      const textHeight=official&&svg?0:Math.max(100,lines*46+28),artHeight=svg?912*dimensions[3]/dimensions[2]:0;
      const sourceBottom=44+textHeight+artHeight,baseHeight=Math.max(650,Math.ceil(sourceBottom+330));
      const prior=record?.papers?.[question.id];
      pages.push({key:question.id,questions:[question],svg,official,dimensions,textHeight,artHeight,sourceBottom,height:Math.max(baseHeight,prior?.height||0),state:prior||P.emptyState(baseHeight)});
    }
    for(const blank of record?.extraPages||[]){const prior=record.papers?.[blank.key];pages.push({key:blank.key,questions:[],blank:true,height:prior?.height||blank.height||1400,state:prior||P.emptyState(blank.height||1400),number:blank.number});}
    return pages;
  }
  function sourceMarkup(page){
    if(page.blank)return `<text x="44" y="70" font-family="Georgia,serif" font-size="30" fill="#526174">Pracovní list ${page.number}</text><line x1="44" y1="100" x2="956" y2="100" stroke="#d6dce4"/>`;
    const q=page.questions[0];let source='';
    if(page.textHeight)source=`<foreignObject x="44" y="36" width="912" height="${page.textHeight}"><div xmlns="http://www.w3.org/1999/xhtml" style="font:32px/1.4 Arial,sans-serif;color:#202730;white-space:pre-wrap;overflow-wrap:anywhere">${e(q.text)}</div></foreignObject>`;
    if(page.svg){const y=44+page.textHeight;source+=page.svg.replace(/<svg\b[^>]*>/,`<svg x="44" y="${y}" width="912" height="${page.artHeight}" viewBox="${page.dimensions.join(' ')}" preserveAspectRatio="xMidYMin meet">`);}
    source+=`<line x1="44" y1="${page.sourceBottom+38}" x2="956" y2="${page.sourceBottom+38}" stroke="#e4e5e3"/><text x="44" y="${page.sourceBottom+72}" fill="#8a9199" font-family="Arial,sans-serif" font-size="18">Prostor pro výpočty a poznámky</text>`;
    return source;
  }
  function paperSvg(page,readOnly=false){
    const pattern='grid-'+page.key.replace(/[^a-zA-Z0-9-]/g,'');
    return `<div class="paper-surface" style="aspect-ratio:1000/${page.height}"><svg class="study-paper-svg" xmlns="http://www.w3.org/2000/svg" data-paper="${e(page.key)}" viewBox="0 0 1000 ${page.height}" aria-label="${e(page.blank?'Pracovní list '+page.number:'Zadání a pracovní papír: '+page.questions.map(q=>questionLabel(q)).join(', '))}" role="${readOnly?'img':'group'}"><desc>${page.questions.map(q=>e(q.text)).join(' ')}</desc><defs><pattern id="${pattern}" width="50" height="50" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="1" fill="#d9dfe5"/></pattern></defs><rect width="1000" height="${page.height}" fill="#fffefa"/><rect class="paper-grid" x="0" y="${page.blank?105:page.sourceBottom+90}" width="1000" height="${page.height}" fill="url(#${pattern})"/><g class="question-source" pointer-events="none">${sourceMarkup(page)}</g><g class="ink-layer">${readOnly?page.state.objects.map(o=>P.objectMarkup(o,false)).join(''):''}</g><g class="ink-preview" pointer-events="none"></g></svg></div>`;
  }
  function questionLabel(q){return q.practiceIndex?String(q.practiceIndex)+(q.no?' (původní '+q.no+')':''):q.no||String(qs.indexOf(q)+1);}
  function answersMarkup(q,index){
    const label=q.practiceIndex||q.no||String(index+1),answer=ans[q.id];
    if(q.type==='draw')return `<p class="construction-note">Úloha ${e(label)} · Konstrukci proveď přímo v zadání. Po odevzdání ji porovnáš se vzorovým řešením.</p>`;
    if(q.type==='short')return `<div class="ansb final-short"><label for="final-${e(q.id)}">Finální odpověď ${e(label)}</label><input id="final-${e(q.id)}" type="text" value="${e(answer??'')}" aria-label="Odpověď na úlohu ${e(label)}" data-id="${e(q.id)}" autocomplete="off" oninput="ans[this.dataset.id]=this.value"></div>`;
    if(q.type==='choice')return `<fieldset class="final-choice"><legend>Finální odpověď ${e(label)}</legend><div class="opts">${q.options.map((option,k)=>`<label class="po"><input type="radio" name="final-${e(q.id)}" data-id="${e(q.id)}" data-k="${k}" ${answer===k?'checked':''} onclick="pick(this)"><span class="bub">${L[k]}</span>${option?`<span>${e(option)}</span>`:''}</label>`).join('')}</div></fieldset>`;
    return `<fieldset class="final-series"><legend>Finální odpovědi ${e(label)}</legend><table class="tfp"><thead><tr><th scope="col">Tvrzení</th><th scope="col">ANO</th><th scope="col">NE</th></tr></thead><tbody>${q.stmts.map((s,k)=>`<tr><td>${e(s.t)}</td>${[true,false].map(v=>`<td><input class="sq" type="radio" name="final-${e(q.id)}-${k}" data-id="${e(q.id)}" data-k="${k}" data-v="${v?'1':'0'}" ${(answer||[])[k]===v?'checked':''} aria-label="Úloha ${e(label)}, ${e(s.t)} – ${v?'ANO':'NE'}" onclick="pickS(this)"></td>`).join('')}</tr>`).join('')}</tbody></table></fieldset>`;
  }
  function workspaceToolbar(pages){
    return `<div class="workspace-top"><button onclick="leaveT()">Uložit a zpět</button><div class="workspace-title"><strong>${e(cur.title)}</strong><span id="study-save-status" role="status" aria-live="polite">Připraveno k ukládání</span></div><span id="timer">${cur.minutes?'':'Bez limitu'}</span><button class="p" onclick="CermatUpgrade.confirmFinish()">Odevzdat</button></div><div class="workspace-tools" role="region" aria-label="Nástroje pracovního papíru"><div class="tool-primary"><label class="tool-select"><span>Nástroj</span><select id="paper-tool" aria-label="Nástroj">${Object.entries(tools).map(([key,label])=>`<option value="${key}" ${settings.tool===key?'selected':''}>${label}</option>`).join('')}</select></label><div class="tool-actions"><button data-study="undo" id="paper-undo" aria-label="Zpět v kreslení" disabled>Zpět</button><button data-study="redo" id="paper-redo" aria-label="Znovu v kreslení" disabled>Znovu</button></div><div class="zoom-controls"><button data-study="zoom-out" aria-label="Oddálit papír">−</button><button data-study="zoom-fit" id="paper-zoom" aria-label="Přizpůsobit papír">100 %</button><button data-study="zoom-in" aria-label="Přiblížit papír">+</button></div><label class="question-picker"><span>Úloha</span><select id="paper-question" aria-label="Přejít na úlohu">${pages.map((p,i)=>`<option value="${e(p.key)}" ${active?.currentQuestion===p.key?'selected':''}>${p.blank?'Pracovní list '+p.number:'Úloha '+p.questions.map(q=>questionLabel(q)).join(', ')}</option>`).join('')}</select></label></div><details class="instrument-options" id="instrument-options"><summary>Nastavení nástroje a přesná konstrukce</summary><div class="instrument-fields"><label>Barva<input type="color" id="paper-color" value="${settings.color}"></label><label>Tloušťka<select id="paper-width"><option value="1.2" ${settings.width===1.2?'selected':''}>Tenká</option><option value="2.4" ${settings.width===2.4?'selected':''}>Střední</option><option value="4.8" ${settings.width===4.8?'selected':''}>Silná</option></select></label><label class="snap-setting"><input type="checkbox" id="paper-snap" ${settings.snap?'checked':''}>Přichytit k bodům a průsečíkům</label><label data-option-for="length">Délka (mm)<input type="number" min="0.1" max="1000" step="0.1" id="paper-length" value="${e(settings.length)}" placeholder="tažením"></label><label data-option-for="radius">Poloměr (mm)<input type="number" min="0.1" max="1000" step="0.1" id="paper-radius" value="${e(settings.radius)}" placeholder="tažením"></label><label data-option-for="angle">Úhel (°)<input type="number" min="0.1" max="180" step="0.1" id="paper-angle" value="${e(settings.angle)}" placeholder="změřit třemi body"></label><label data-option-for="label">Název bodu<input type="text" maxlength="20" id="paper-label" value="${e(settings.label)}" placeholder="A, B, C…"></label><label data-option-for="text" class="annotation-text-field">Text nebo matematický výraz<textarea id="paper-text" rows="2" placeholder="Např. (a + b)² = a² + 2ab + b²">${e(settings.text)}</textarea></label><label data-option-for="text">Velikost textu<select id="paper-size">${[24,32,40,48].map(size=>`<option value="${size}" ${settings.size===size?'selected':''}>${size===24?'Menší':size===32?'Běžná':size===40?'Větší':'Velká'}</option>`).join('')}</select></label></div><div class="selection-actions"><span id="selected-description">Vyber anotaci pro úpravu.</span><button data-study="ruler-line" id="ruler-line" hidden>Narýsovat podél pravítka</button><button data-study="delete" id="delete-annotation" disabled>Odstranit vybranou anotaci</button><button data-study="clear" class="d">Vymazat anotace tohoto listu</button></div><p class="instrument-scale">Měření patří pracovnímu papíru a zůstává stejné při přiblížení. Rozměry úlohy čti ze zadání; náčrtek nemusí být v měřítku.</p></details><div class="instrument-hint"><span id="paper-tool-hint" role="status"></span><button data-study="close-polygon" id="close-polygon" hidden>Uzavřít mnohoúhelník</button></div></div>`;
  }
  function runView(){
    const pages=pageDefinitions(qs,active);
    return `${workspaceToolbar(pages)}<div class="workspace-introduction"><span>${qs.length} úloh · ${tpts({...cur,questions:qs})} bodů</span><span>Práce se ukládá automaticky. Při odchodu se čas pozastaví.</span></div><div class="exam-paper-stack">${pages.map(page=>`<section class="exam-page" id="page-${e(page.key)}" data-page-key="${e(page.key)}"><div class="exam-page-heading"><h2>${page.blank?'Pracovní list '+page.number:'Úloha '+page.questions.map(q=>questionLabel(q)).join(', ')}</h2><button class="text-button" data-study="activate" data-key="${e(page.key)}">Pracovat na tomto listu</button></div>${page.questions[0]?.practiceSource?`<p class="practice-source">${e(page.questions[0].practiceSource)}</p>`:''}${paperSvg(page)}<div class="final-answers">${page.questions.map(q=>answersMarkup(q,qs.indexOf(q))).join('')}</div><div class="page-footer"><button class="text-button" data-study="more-space" data-key="${e(page.key)}">+ Více místa na tomto listu</button>${page.questions.some(q=>q.hint)?page.questions.filter(q=>q.hint).map(q=>`<details class="paper-hint"><summary>Nápověda ${e(q.no||'')}</summary><p>${e(q.hint)}</p></details>`).join(''):''}</div></section>`).join('')}</div><div class="workspace-bottom"><button onclick="CermatUpgrade.addBlank()">+ Přidat prázdný pracovní list</button><button class="p" onclick="CermatUpgrade.confirmFinish()">Odevzdat test</button></div><dialog id="finish-dialog"><h2>Odevzdat test?</h2><p>Vyhodnotí se finální odpovědi. Poznámky a konstrukce zůstanou uložené spolu s výsledkem.</p><div class="row"><button onclick="document.getElementById('finish-dialog').close()">Ještě pokračovat</button><button class="p" onclick="document.getElementById('finish-dialog').close();finish()">Odevzdat</button></div></dialog>`;
  }
  function setSaveStatus(message,error=false){const element=document.getElementById('study-save-status');if(element){element.textContent=message;element.classList.toggle('save-error',error);}}
  function capture(persist=true){
    if(!active||active.status!=='in-progress'||saving)return;
    saving=true;
    if(editor)active.papers=editor.export();
    active.answers=copy(ans);active.left=Math.max(0,left);active.updatedAt=Math.max(Date.now(),(active.updatedAt||0)+1);active.scrollY=window.scrollY;active.viewportWidth=innerWidth;active.tools=copy(settings);
    saving=false;
    if(!persist)return;
    const token=++revision;setSaveStatus('Ukládám…');
    store.save(active).then(result=>{if(token!==revision)return;setSaveStatus(result.saved?'Uloženo v tomto prohlížeči':'Neuloženo: úložiště je nedostupné. Stáhni zálohu postupu.',!result.saved);});
  }
  function pauseClock(){if(view==='run'&&cur?.minutes&&deadline&&!clockPaused)left=Math.max(0,Math.ceil((deadline-Date.now())/1000));clearInterval(timerId);timerId=null;clockPaused=true;}
  function startClock(){
    clearInterval(timerId);clockPaused=false;
    if(!cur?.minutes){tick();return;}
    deadline=Date.now()+left*1000;tick();
    timerId=setInterval(()=>{
      if(view!=='run'||clockPaused)return;
      left=Math.max(0,Math.ceil((deadline-Date.now())/1000));tick();
      if(Date.now()-lastTimerSave>5000){capture();lastTimerSave=Date.now();}
      if(left<=0)finish();
    },500);
  }
  function restored(record){
    if(record.kind!=='topic-practice')return{test:copy(record.test),questions:copy(record.questions),result:copy(record.result||null)};
    root.CermatPractice.refresh();return root.CermatTopics.hydrate(record,root.CermatPractice.catalog);
  }
  function startRecord(record){
    let content;try{content=restored(record);}catch(error){notify(error.message);return false;}
    if(view==='run'){pauseClock();capture();}
    active=copy(record);cur=content.test;qs=content.questions;ans=copy(record.answers||{});wp={};pads={};hints=new Set(record.hints||[]);left=record.left;view='run';
    Object.assign(settings,record.tools||{});render();startClock();
    requestAnimationFrame(()=>requestAnimationFrame(()=>{
      if(record.scrollY!==undefined&&Math.abs((record.viewportWidth||innerWidth)-innerWidth)<2)window.scrollTo(0,record.scrollY);
      else if(record.scrollY!==undefined&&record.currentQuestion)jump(record.currentQuestion,false);
      capture();
    }));
  }
  async function start(test,force){
    await store.ready;
    if(test.kind==='topic-practice'&&active?.kind==='topic-practice'){root.CermatPractice.repeat(active);return;}
    const previous=!test.temp?store.records.get(test.id):null;
    if(previous?.status==='in-progress'){startRecord(previous);return;}
    if(view==='run'){pauseClock();capture();}
    const ordered=(force||test.shuffle||getP().rq)?[...test.questions].sort(()=>Math.random()-.5):test.questions;
    const questions=(force||getP().ro)?ordered.map(q=>q.type==='choice'?shufOpts(q):q):ordered;
    const attemptId=G.id(),key=test.temp?test.id+'::'+attemptId:test.id;
    startRecord({version:1,key,attemptId,test:copy(test),questions:copy(questions),answers:{},papers:{},extraPages:[],left:(test.minutes||0)*60,currentQuestion:questions[0]?.id||'',updatedAt:Date.now(),status:'in-progress'});
  }
  function onEditorStatus(info){
    const hint=document.getElementById('paper-tool-hint');if(hint)hint.textContent=info.message;
    for(const [id,value] of [['paper-undo',!info.undo],['paper-redo',!info.redo]]){const b=document.getElementById(id);if(b)b.disabled=value;}
    const z=document.getElementById('paper-zoom');if(z)z.textContent=Math.round(info.zoom*100)+' %';
    const close=document.getElementById('close-polygon');if(close)close.hidden=info.tool!=='polygon'||info.staged<3;
    if(active&&info.page){active.currentQuestion=info.page;const picker=document.getElementById('paper-question');if(picker)picker.value=info.page;}
    updateOptions(info.selected?.type||settings.tool);
  }
  function updateOptions(tool){
    const fields={length:['segment','line','ruler'],radius:['circle','arc'],angle:['angle'],label:['point'],text:['text']};
    document.querySelectorAll('[data-option-for]').forEach(el=>{el.hidden=!fields[el.dataset.optionFor]?.includes(tool);});
  }
  function selectedObject(object){
    const desc=document.getElementById('selected-description');if(desc)desc.textContent=object?(tools[object.type]||'Anotace')+' · lze přesunout, upravit nebo odstranit':'Vyber anotaci pro úpravu.';
    const button=document.getElementById('delete-annotation');if(button)button.disabled=!object;
    const ruler=document.getElementById('ruler-line');if(ruler)ruler.hidden=object?.type!=='ruler';
    if(!object){for(const [key,value]of Object.entries(settings)){const input=document.getElementById('paper-'+key);if(input&&key!=='tool'){if(key==='snap')input.checked=!!value;else if(input.value!==String(value))input.value=value;}}return;}
    const values={color:object.color,width:object.width,text:object.text,label:object.label,size:object.size,length:object.a&&object.b?G.mm(G.distance(object.a,object.b)):null,radius:object.r?G.mm(object.r):null,angle:object.type==='angle'?G.angle(object.a,object.v,object.b):null};
    for(const [key,value]of Object.entries(values)){if(value===undefined||value===null)continue;const input=document.getElementById('paper-'+key),next=typeof value==='number'?Math.round(value*1000)/1000:value;if(input&&input.value!==String(next))input.value=next;}
    updateOptions(object.type);
  }
  function bindWorkspace(){
    const definitions=pageDefinitions(qs,active);
    const desiredPage=active.currentQuestion;
    editor=new P.Editor(document.getElementById('app'),definitions,{...settings,onChange:()=>{if(!rendering)capture();},onStatus:onEditorStatus,onSelection:selectedObject});
    if(desiredPage&&editor.pages.has(desiredPage))editor.activate(desiredPage);
    observer=new IntersectionObserver(entries=>{if(!editor||view!=='run')return;const visible=entries.filter(x=>x.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible.length&&settings.tool==='navigate')editor.activate(visible[0].target.dataset.pageKey);},{rootMargin:'-180px 0px -45% 0px'});
    document.querySelectorAll('[data-page-key]').forEach(el=>observer.observe(el));
    if(typeof ResizeObserver!=='undefined'){
      toolbarObserver=new ResizeObserver(()=>{
        const top=document.querySelector('.workspace-top'),tools=document.querySelector('.workspace-tools');if(!top||!tools)return;
        tools.style.top='calc('+top.offsetHeight+'px + env(safe-area-inset-top, 0px))';const margin=top.offsetHeight+tools.offsetHeight+16+(parseFloat(getComputedStyle(top).top)||0);
        document.querySelectorAll('.exam-page').forEach(page=>{page.style.scrollMarginTop=margin+'px';});
      });
      toolbarObserver.observe(document.querySelector('.workspace-top'));toolbarObserver.observe(document.querySelector('.workspace-tools'));
    }
    tick();
  }
  function jump(key,save=true){
    if(!editor?.pages.has(key))return;editor.activate(key);active.currentQuestion=key;
    const element=document.getElementById('page-'+key);if(element)element.scrollIntoView({block:'start',behavior:'instant'});if(save)capture();
  }
  function addBlank(){capture(false);const key='blank-'+G.id(),number=(active.extraPages||[]).length+1;active.extraPages.push({key,number,height:1400});active.currentQuestion=key;capture();render();requestAnimationFrame(()=>jump(key));}
  function moreSpace(key){
    const page=editor?.pages.get(key);if(!page)return;page.state.height+=350;page.height=page.state.height;page.svg.closest('.paper-surface').style.aspectRatio='1000/'+page.state.height;page.svg.querySelectorAll('rect[height]').forEach(rect=>{if(rect.parentElement===page.svg)rect.setAttribute('height',page.state.height);});editor.applyView(page);capture();
  }
  function resultDetail(row,index){
    if(row.q.type!=='draw')return legacy.det(row,index);
    const definition=pageDefinitions([row.q],active)[0];
    return `<div class="construction-result">${paperSvg(definition,true)}<details class="solution-disclosure"><summary>Vzorové řešení a oficiální podklad</summary>${cleanSvg(row.q.sol)||'<p>U této úlohy není obrázkové řešení dostupné.</p>'}</details>${row.pend?`<p>Porovnej svoji konstrukci se vzorem. Její body potvrzuješ sám.</p><div class="row"><button class="p" onclick="selfJ(${index},1)">Mám správně</button><button onclick="selfJ(${index},0)">Mám špatně</button></div>`:`<p class="${row.g?'ok':'bad'}">${row.g?'Správně':'Špatně'} · ${row.g}/${row.m} bodů · vlastní hodnocení</p><button onclick="selfJ(${index},${row.g?0:1})">Změnit vlastní hodnocení</button>`}</div>`;
  }
  function resultView(){
    const pending=res.rows.filter(row=>row.pend).length,wrong=res.rows.filter(row=>row.g<row.m);
    let html=`<div class="result-heading"><span class="editorial-label">${e(cur.title)}</span><h1>${pending?'Průběžný výsledek':'Výsledek testu'}</h1></div><div class="card result-score"><div class="big ${res.pct>=50?'ok':'bad'}">${res.pct} %</div><div><strong>${res.got} z ${res.tot} bodů</strong><p class="mut">${pending?`${pending} konstrukční úlohy ještě čekají na tvoje porovnání se vzorem. Body nejsou konečné.`:'Vyhodnoceny jsou finální odpovědi. Pracovní poznámky zůstávají uložené.'}</p></div></div>`;
    html+=res.rows.map((row,index)=>`<article class="card answer-review"><div class="review-heading"><h2>Úloha ${e(questionLabel(row.q))}</h2><span>${row.pend?'?':row.g}/${row.m} b.</span></div>${row.q.practiceSource?`<p class="practice-source">${e(row.q.practiceSource)}</p>`:''}${row.q.type!=='draw'?(row.q.svg?`<details class="result-source"><summary>Původní zadání</summary>${cleanSvg(row.q.svg)}</details>`:`<p class="review-question">${e(row.q.text)}</p>`):''}${det(row,index)}${row.g<row.m&&!row.pend&&row.q.hint?`<details class="paper-hint"><summary>Nápověda</summary><p>${e(row.q.hint)}</p></details>`:''}</article>`).join('');
    html+=active?.kind==='topic-practice'?root.CermatPractice.resultActions(active):`<div class="row"><button class="p" onclick="startT(cur)">Zkusit znovu</button>${wrong.length?`<button onclick="retryW()">Procvičit jen chyby (${wrong.length})</button>`:''}<button onclick="go('home')">Zpět na testy</button><button onclick="go('history')">Historie pokusů</button></div>`;
    if(active?.papers){const pages=pageDefinitions(qs,active);html+=`<details class="saved-paper-review"><summary>Otevřít celý uložený pracovní papír</summary><div class="exam-paper-stack">${pages.map(page=>`<section class="exam-page"><h2>${page.blank?'Pracovní list '+page.number:'Úloha '+page.questions.map(q=>questionLabel(q)).join(', ')}</h2>${paperSvg(page,true)}</section>`).join('')}</div></details>`;}
    return html;
  }
  function finishTest(){
    if(!active||active.status==='completed')return;
    pauseClock();capture(false);const originalCheck=checkDraw;
    if(active.kind==='topic-practice'){
      const rows=qs.map(q=>{const a=ans[q.id],[g,m]=grade(q,a);return{q,a,g,m,pend:q.type==='draw',auto:0,msg:''};});
      const got=rows.reduce((n,r)=>n+r.g,0),tot=rows.reduce((n,r)=>n+r.m,0);
      res={got,tot,pct:tot?Math.round(got/tot*100):0,rows,hints:hints.size,imgs:{}};view='result';
    }else{try{checkDraw=()=>null;wp={};legacy.finish();}finally{checkDraw=originalCheck;}}
    active.answers=copy(ans);active.result=active.kind==='topic-practice'?root.CermatTopics.packResult(res):copy(res);active.status='completed';active.updatedAt=Date.now();active.left=left;
    store.complete(active).then(saved=>{if(!saved.saved)notify('Výsledek se nepodařilo uložit. Stáhni úplnou zálohu, než stránku zavřeš.');});render();
  }
  async function openHistory(id){
    const record=await store.historyRecord(id);if(!record?.result){notify('Tento pracovní list se v dostupném úložišti nepodařilo najít.');return;}
    let content;try{content=restored(record);}catch(error){notify(error.message);return;}
    if(view==='run'){pauseClock();capture();}
    active=copy(record);cur=content.test;qs=content.questions;ans=copy(record.answers);res=content.result;view='result';render();
  }
  function notify(message){let element=document.getElementById('study-notification');if(!element){element=document.createElement('p');element.id='study-notification';element.setAttribute('role','status');document.getElementById('app').prepend(element);}element.textContent=message;}
  function progressBackup(){
    return `<header class="sethd"><button onclick="go('settings')">‹ Zpět</button><h1>Záloha postupu</h1></header><section class="card complete-backup"><h2>Odpovědi, výsledky a pracovní papíry</h2><p class="mut">Postup se ukládá v tomto prohlížeči. Zálohu si můžeš stáhnout jako soubor.</p><button id="download-study-backup" onclick="CermatUpgrade.downloadBackup()">Stáhnout zálohu postupu</button></section>`;
  }
  async function downloadBackup(){
    capture();await store.ready;
    const payload={format:'cermat-study-backup',version:1,exportedAt:new Date().toISOString(),tests:[],stats:copy(stats),trash:[],preferences:getP(),study:await store.export()};
    const url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='CERMAT-zaloha-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
  }
  
  
  function eventHandlers(){
    document.getElementById('app').addEventListener('input',event=>{
      if(view==='run'&&event.target.closest('.final-answers'))capture();
      const element=event.target;if(view!=='run'||!editor||!element.id.startsWith('paper-')||['paper-question','paper-tool'].includes(element.id))return;
      const key=element.id.slice(6),numeric=['width','size','length','radius','angle'].includes(key),value=key==='snap'?element.checked:numeric?(element.value===''?'':Number(element.value)):element.value;
      if(numeric&&value!==''&&(!Number.isFinite(value)||value<=0||value>1000||key==='angle'&&value>180))return;
      settings[key]=value;editor.configure({[key]:value});if(editor.selectedObject()&&key!=='snap'&&(!numeric||value!==''))editor.editSelected({[key]:value},false);capture();
    });
    document.getElementById('app').addEventListener('change',event=>{
      const element=event.target;
      if(view!=='run'||!editor)return;
      if(element.id==='paper-question'){jump(element.value);return;}
      if(element.id==='paper-tool'){settings.tool=element.value;editor.setTool(element.value);selectedObject(null);updateOptions(element.value);capture();return;}
      if(element.id.startsWith('paper-')){
        const key=element.id.slice(6),numeric=['width','size','length','radius','angle'].includes(key),value=key==='snap'?element.checked:numeric?(element.value===''?'':Number(element.value)):element.value;
        if(numeric&&value!==''&&(!Number.isFinite(value)||value<=0||value>1000||key==='angle'&&value>180))return;
        settings[key]=value;editor.configure({[key]:value});
        if(editor.selectedObject()&&key!=='snap')editor.editSelected({[key]:value});capture();
      }
      if(element.closest('.final-answers'))capture();
    });
    document.getElementById('app').addEventListener('click',event=>{
      const button=event.target.closest('[data-study]');
      if(view==='run'&&event.target.closest('.final-answers'))capture();
      if(!button||!editor)return;
      const action=button.dataset.study;
      if(action==='undo')editor.undo();if(action==='redo')editor.redo();if(action==='delete')editor.removeSelected();if(action==='ruler-line')editor.lineAlongRuler();
      if(action==='zoom-in')editor.zoom(editor.page().state.view.zoom*1.25);if(action==='zoom-out')editor.zoom(editor.page().state.view.zoom/1.25);if(action==='zoom-fit')editor.zoom(1);
      if(action==='close-polygon')editor.closePolygon();if(action==='activate')editor.activate(button.dataset.key);if(action==='more-space')moreSpace(button.dataset.key);
      if(action==='clear'){if(button.dataset.confirm==='yes'){editor.clear();delete button.dataset.confirm;button.textContent='Vymazat anotace tohoto listu';}else{button.dataset.confirm='yes';button.textContent='Opravdu vymazat anotace?';setTimeout(()=>{if(button.isConnected){delete button.dataset.confirm;button.textContent='Vymazat anotace tohoto listu';}},4000);}}
    });
    addEventListener('pagehide',()=>{pauseClock();capture();});
    document.addEventListener('visibilitychange',()=>{if(view!=='run')return;if(document.hidden){pauseClock();capture();}else startClock();});
  }
  function install(){
    legacy={render,go,finish,det,selfJ,setV,applyPrefs,retryW,getP,srow};
    store=new root.CermatStudyStore.StudyStore();fact=selectFact();
    store.ready=store.ready.then(()=>root.CermatStudent.restore(store)).catch(()=>{
      // The previous edition's data stays available if the browser blocks migration.
    }).then(()=>{
      storeReady=true;
      if(Object.keys(stats).length)idbGet('cermat-student-stats-snapshots').then(items=>{
        if(!items?.length||Date.now()-items[0].ts>864e5)snap('Denní záloha');
      }).catch(()=>{});
    });
    getP=function(){return{...legacy.getP(),th:'dark'};};
    srow=function(title,description,control){return title==='Téma'?'':legacy.srow(title,description,control);};
    applyPrefs=function(){legacy.applyPrefs();document.documentElement.dataset.theme='dark';};
    topNav=navigation;home=homeView;tlist=library;runP=runView;initWp=bindWorkspace;startT=start;det=resultDetail;result=resultView;
    go=function(next){if(view==='run'&&next!=='run'){pauseClock();capture();}legacy.go(next);};
    leaveT=function(){go('home');};
    finish=finishTest;
    selfJ=function(index,correct){legacy.selfJ(index,correct);if(active){res.rows[index].manual=true;active.result=active.kind==='topic-practice'?root.CermatTopics.packResult(res):copy(res);active.updatedAt=Date.now();store.complete(active);render();}};
    retryW=function(){if(active?.kind==='topic-practice')root.CermatPractice.repeat(active,true);else legacy.retryW();};
    backup=progressBackup;
    setV=function(){return legacy.setV()+`<section class="card"><h2>Pracovní papír a uložená práce</h2><p class="mut">Každý test má svůj rozepsaný pokus. Poznámky ani odpovědi jiného termínu se nepřepisují. Postup je uložen v tomto prohlížeči.</p><div class="row"><button onclick="go('history')">Rozepsané a historie</button><button onclick="go('progress-backup')">Záloha postupu</button></div><p class="mut">Konstrukce se porovnávají se vzorem a hodnotí ručně. Rukopis se automaticky nevyhodnocuje. Přichytávání využívá vlastní body a vytvořené průsečíky; body ve skenovaném zadání se nerozpoznávají.</p></section>`;};
    render=function(){
      rendering=true;
      if(editor){if(active&&active.status==='in-progress')active.papers=editor.export();editor.destroy();editor=null;}
      if(observer){observer.disconnect();observer=null;}
      if(toolbarObserver){toolbarObserver.disconnect();toolbarObserver=null;}
      if(['topics','topic'].includes(view)){document.getElementById('app').className='practice-view';document.getElementById('app').innerHTML=root.CermatPractice.view(view);document.body.classList.remove('mkon');window.scrollTo(0,0);root.CermatPractice.afterRender();}
      else if(view==='history'){document.getElementById('app').className='history-view';document.getElementById('app').innerHTML=historyView();document.body.classList.remove('mkon');window.scrollTo(0,0);}else legacy.render();
      if(view==='home')document.querySelectorAll('.year-card').forEach(details=>details.addEventListener('toggle',()=>{const year=Number(details.dataset.year);details.open?expanded.add(year):expanded.delete(year);}));
      if(view==='settings')document.querySelectorAll('.srow').forEach(row=>{const label=row.querySelector('b')?.textContent;if(label==='Automatické vyhodnocení kresby'||label==='Přísnost vyhodnocení')row.remove();});
      rendering=false;
    };
    root.CermatPractice.install({store,getTests:()=>tests,start:startRecord,navigate:next=>go(next),refresh:()=>render(),notify,artwork:cleanSvg,bankReady:()=>storeReady});
    eventHandlers();
    store.ready.then(()=>{if(view==='home'||view==='history')render();});
  }
  root.CermatUpgrade={install,get store(){return store;},get active(){return active;},get editor(){return editor;},get settings(){return settings;},pageDefinitions,officialYear,selectFact,capture,jump,addBlank,downloadBackup,openHistory,toggleMenu:button=>{const open=button.closest('.topnav').classList.toggle('menu-open');button.setAttribute('aria-expanded',String(open));},resume:async key=>{await store.ready;const record=store.records.get(key);if(record)startRecord(record);},nextFact:()=>{fact=selectFact();const section=document.querySelector('.fact-editorial');if(section)section.outerHTML=factMarkup();},confirmFinish:()=>{const dialog=document.getElementById('finish-dialog');if(dialog?.showModal)dialog.showModal();else finish();}};
})(window);
